mapper.select:

WHERE t.kind = #{kind}
AND t.status = #{status}

    AND (t.note_no LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%')
         OR s.name LIKE CONCAT('%', #{keyword}, '%') OR t.acceptor LIKE CONCAT('%', #{keyword}, '%'))

AND t.due_date <= #{dueBefore}
ORDER BY t.due_date, t.id


WHERE ((t.kind = 'RECEIVABLE' AND t.status = 'HELD') OR (t.kind = 'PAYABLE' AND t.status = 'ISSUED'))
  AND t.due_date <= #{dueBefore}
ORDER BY t.due_date
